  <style>
    :root{--pine-950:#061a15;--pine-900:#09251d;--pine-850:#0d3027;--pine-800:#123b30;--pine-700:#1b5242;--acid:#dffc62;--ember:#f27b4a;--cream:#fffdf6;--oat:#f0ecdf;--moss:#b7c9a3;--ink:#16231e;--sky:#b8dce0;--line:rgba(9,37,29,.12);--shadow:0 30px 90px -48px rgba(6,26,21,.5);--shadow-dark:0 32px 90px -44px rgba(0,0,0,.64);--display:'Fraunces',serif;--sans:'DM Sans',sans-serif}
    *{box-sizing:border-box}html{background:var(--oat);scroll-behavior:smooth}body{margin:0;overflow-x:hidden;background:var(--oat);color:var(--ink);font-family:var(--sans);text-rendering:optimizeLegibility}body.menu-open,body.modal-open{overflow:hidden}button,input,textarea,select{font:inherit}button,a{-webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}::selection{background:var(--acid);color:var(--pine-950)}
