    #scrollProgress{position:fixed;z-index:180;top:0;left:0;width:100%;height:3px;background:var(--acid);transform:scaleX(0);transform-origin:left center}.site-header{position:fixed;inset:0 0 auto;z-index:120;padding-inline:20px;pointer-events:none}.nav{width:min(1240px,100%);height:72px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0 14px 0 18px;color:white;border:1px solid rgba(255,255,255,.12);border-radius:24px;background:rgba(6,26,21,.72);backdrop-filter:blur(22px) saturate(130%);box-shadow:0 22px 60px -42px rgba(0,0,0,.92);pointer-events:auto;transition:.35s ease}.nav.scrolled{height:64px;margin-top:6px;background:rgba(6,26,21,.9)}
    .brand{display:inline-flex;align-items:center;gap:11px;min-width:0}.brand-mark{width:42px;height:42px;display:grid;place-items:center;border-radius:15px;background:var(--acid);color:var(--pine-950);flex:none}.brand-name{display:block;font-family:var(--display);font-size:20px;font-weight:700;line-height:1}.brand-sub{display:block;margin-top:4px;font-size:8px;font-weight:700;text-transform:uppercase;letter-spacing:.16em;color:rgba(255,255,255,.5);white-space:nowrap}.nav-links{display:flex;align-items:center;gap:25px;font-size:12px;font-weight:700}.nav-links a{color:rgba(255,255,255,.76);transition:.2s}.nav-links a:hover,.nav-links a.active{color:white}.nav-actions{display:flex;align-items:center;gap:9px}.nav-icon{width:42px;height:42px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.12);border-radius:15px;background:rgba(255,255,255,.05);color:white;cursor:pointer}.ticket-btn{height:42px;padding:0 17px;display:inline-flex;align-items:center;justify-content:center;border-radius:14px;background:var(--acid);color:var(--pine-950);font-size:11px;font-weight:800;white-space:nowrap}.mobile-trigger{display:none}
    .mobile-menu{position:fixed;inset:0;z-index:160;visibility:hidden;pointer-events:none}.mobile-menu.open{visibility:visible;pointer-events:auto}.menu-backdrop{position:absolute;inset:0;background:rgba(3,15,12,.72);opacity:0;transition:.3s}.mobile-menu.open .menu-backdrop{opacity:1}.menu-panel{position:absolute;top:0;right:0;width:min(420px,92vw);height:100%;padding:24px;background:var(--cream);transform:translateX(100%);transition:.38s cubic-bezier(.2,.75,.2,1);overflow:auto}.mobile-menu.open .menu-panel{transform:none}.menu-head{display:flex;justify-content:space-between;align-items:center}.menu-close{width:44px;height:44px;border:1px solid var(--line);border-radius:15px;background:white;cursor:pointer}.menu-links{display:grid;gap:5px;margin-top:40px}.menu-links a{padding:16px 4px;border-bottom:1px solid var(--line);font-family:var(--display);font-size:28px}.menu-cta{margin-top:28px;display:grid;gap:10px}
    .btn{min-height:48px;padding:0 21px;display:inline-flex;align-items:center;justify-content:center;gap:10px;border:0;border-radius:16px;font-size:12px;font-weight:800;cursor:pointer;transition:transform .2s ease,box-shadow .2s ease,background .2s}.btn:hover{transform:translateY(-2px)}.btn-acid{background:var(--acid);color:var(--pine-950);box-shadow:0 18px 52px -30px rgba(223,252,98,.72)}.btn-dark{background:var(--pine-900);color:white}.btn-cream{background:var(--cream);color:var(--pine-900)}.btn-outline{border:1px solid rgba(9,37,29,.16);background:transparent;color:var(--pine-900)}.btn-white-outline{border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.04);color:white}.eyebrow{display:inline-flex;align-items:center;gap:9px;font-size:10px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:var(--pine-700)}.eyebrow::before{content:'';width:22px;height:1px;background:currentColor}.eyebrow.light{color:var(--acid)}.title-xl{font-family:var(--display);font-size:clamp(52px,7.8vw,112px);line-height:.88;letter-spacing:-.06em;margin:0}.title-lg{font-family:var(--display);font-size:clamp(40px,5vw,74px);line-height:.98;letter-spacing:-.045em;margin:0}.title-md{font-family:var(--display);font-size:clamp(34px,4vw,58px);line-height:1;letter-spacing:-.04em;margin:0}.muted{color:rgba(22,35,30,.62)}
    .hero{min-height:710px;padding:142px 0 72px;background:var(--pine-950);color:white;position:relative;overflow:hidden}.hero::before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(6,26,21,.95),rgba(6,26,21,.78) 47%,rgba(6,26,21,.22) 78%,rgba(6,26,21,.6)),url('https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=2200&q=88') center/cover no-repeat}.hero::after{content:'';position:absolute;inset:auto 0 0;height:190px;background:linear-gradient(transparent,var(--pine-950))}.hero-inner{position:relative;z-index:3;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(340px,.72fr);gap:68px;align-items:end}.hero-copy p{max-width:680px;margin:24px 0 0;font-size:18px;line-height:1.72;color:rgba(255,255,255,.72)}.hero-search{margin-top:32px;position:relative}.search-box{display:grid;grid-template-columns:54px 1fr auto;align-items:center;gap:8px;padding:8px;border-radius:22px;background:var(--cream);box-shadow:var(--shadow-dark)}.search-box svg{margin-left:13px;color:var(--pine-700)}.search-box input{height:52px;border:0;outline:0;background:transparent;color:var(--ink);font-size:14px;min-width:0}.search-box .btn{min-height:52px}.suggestions{position:absolute;top:calc(100% + 10px);left:0;right:0;z-index:15;display:none;padding:10px;border-radius:20px;background:var(--cream);box-shadow:var(--shadow-dark);color:var(--ink)}.suggestions.open{display:grid}.suggestion{width:100%;display:flex;justify-content:space-between;gap:16px;padding:13px;border:0;border-radius:14px;background:none;text-align:left;cursor:pointer}.suggestion:hover{background:rgba(9,37,29,.06)}.suggestion strong{font-size:11px}.suggestion span{font-size:9px;color:rgba(22,35,30,.45)}.popular-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:15px}.popular-chip{padding:9px 12px;border:1px solid rgba(255,255,255,.16);border-radius:999px;background:rgba(255,255,255,.05);color:rgba(255,255,255,.76);font-size:9px;font-weight:700;cursor:pointer}.popular-chip:hover{border-color:var(--acid);color:white}
    .hero-card{padding:27px;border:1px solid rgba(255,255,255,.13);border-radius:30px;background:rgba(7,29,23,.73);backdrop-filter:blur(20px);box-shadow:var(--shadow-dark)}.hero-card-head{display:flex;justify-content:space-between;gap:20px}.hero-card-head small{font-size:9px;text-transform:uppercase;letter-spacing:.15em;color:var(--acid)}.hero-card h2{font-family:var(--display);font-size:34px;line-height:1.04;margin:14px 0 8px}.hero-card p{margin:0;font-size:11px;line-height:1.65;color:rgba(255,255,255,.58)}.answer-stats{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:22px}.answer-stat{padding:15px;border:1px solid rgba(255,255,255,.1);border-radius:18px;background:rgba(255,255,255,.05)}.answer-stat strong{display:block;font-family:var(--display);font-size:28px;color:white}.answer-stat span{display:block;margin-top:3px;font-size:8px;text-transform:uppercase;letter-spacing:.12em;color:rgba(255,255,255,.38)}.hero-route{width:100%;height:120px;margin-top:20px}.hero-route path{fill:none;stroke:var(--acid);stroke-width:3;stroke-linecap:round;stroke-dasharray:9 13;filter:drop-shadow(0 0 8px rgba(223,252,98,.35))}.hero-route circle{fill:var(--acid)}
    .ops-strip{background:var(--pine-950);color:white;border-top:1px solid rgba(255,255,255,.08)}.ops-inner{display:grid;grid-template-columns:repeat(4,1fr)}.ops-item{min-height:82px;padding:18px 22px;display:flex;align-items:center;gap:12px;border-right:1px solid rgba(255,255,255,.08)}.ops-item:last-child{border-right:0}.ops-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:13px;background:rgba(255,255,255,.06);color:var(--acid);flex:none}.ops-item small{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.13em;color:rgba(255,255,255,.36)}.ops-item strong{display:block;margin-top:4px;font-size:10px;color:rgba(255,255,255,.82)}
    .category-section{padding:96px 0}.section-head{display:grid;grid-template-columns:1fr .55fr;gap:50px;align-items:end;margin-bottom:36px}.section-head p{font-size:13px;line-height:1.72}.category-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.category-card{min-height:230px;padding:22px;display:flex;flex-direction:column;justify-content:space-between;border:1px solid var(--line);border-radius:28px;background:var(--cream);box-shadow:var(--shadow);cursor:pointer;transition:.28s;position:relative;overflow:hidden}.category-card::after{content:'';position:absolute;inset:auto -25px -50px auto;width:130px;height:130px;border:1px solid rgba(9,37,29,.08);border-radius:50%}.category-card:hover,.category-card.active{transform:translateY(-5px);border-color:rgba(9,37,29,.26)}.category-card.active{background:var(--pine-900);color:white}.category-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:17px;background:var(--acid);color:var(--pine-950)}.category-card h3{font-family:var(--display);font-size:27px;line-height:1.05;margin:30px 0 9px}.category-card p{margin:0;font-size:10px;line-height:1.6;color:rgba(22,35,30,.54)}.category-card.active p{color:rgba(255,255,255,.55)}.category-foot{display:flex;justify-content:space-between;align-items:center;margin-top:16px;font-size:9px;font-weight:800}.category-count{padding:6px 9px;border-radius:999px;background:rgba(9,37,29,.07)}.category-card.active .category-count{background:rgba(255,255,255,.1)}
    .faq-workspace{padding:100px 0;background:var(--cream)}.workspace{display:grid;grid-template-columns:280px minmax(0,1fr);gap:34px}.filter-sidebar{position:sticky;top:96px;height:max-content;padding:20px;border:1px solid var(--line);border-radius:26px;background:white;box-shadow:var(--shadow)}.filter-sidebar h3{margin:0 0 13px;font-family:var(--display);font-size:25px}.filter-list{display:grid;gap:6px}.filter-btn{width:100%;padding:12px 13px;display:flex;align-items:center;justify-content:space-between;gap:12px;border:0;border-radius:14px;background:transparent;color:var(--ink);text-align:left;font-size:10px;font-weight:700;cursor:pointer}.filter-btn span:last-child{color:rgba(22,35,30,.38)}.filter-btn:hover{background:rgba(9,37,29,.05)}.filter-btn.active{background:var(--pine-900);color:white}.filter-btn.active span:last-child{color:rgba(255,255,255,.5)}.sidebar-note{margin-top:18px;padding:17px;border-radius:18px;background:var(--oat)}.sidebar-note strong{font-family:var(--display);font-size:19px}.sidebar-note p{margin:8px 0 0;font-size:9px;line-height:1.6;color:rgba(22,35,30,.54)}.mobile-filters{display:none;overflow:auto;gap:7px;padding-bottom:4px;margin-bottom:22px;scrollbar-width:none}.mobile-filters::-webkit-scrollbar{display:none}.mobile-filter{white-space:nowrap;padding:10px 13px;border:1px solid var(--line);border-radius:999px;background:white;font-size:9px;font-weight:800}.mobile-filter.active{background:var(--pine-900);color:white;border-color:var(--pine-900)}
    .faq-main-head{display:flex;align-items:flex-end;justify-content:space-between;gap:25px;margin-bottom:22px}.faq-main-head h2{font-family:var(--display);font-size:clamp(34px,4vw,54px);line-height:1;margin:0}.results-count{font-size:9px;text-transform:uppercase;letter-spacing:.13em;color:rgba(22,35,30,.44)}.faq-list{display:grid;gap:10px}.faq-item{border:1px solid var(--line);border-radius:22px;background:white;overflow:hidden;transition:.25s}.faq-item[hidden]{display:none}.faq-item.open{box-shadow:var(--shadow)}.faq-q{width:100%;padding:20px;display:grid;grid-template-columns:38px 1fr 34px;align-items:center;gap:13px;border:0;background:none;text-align:left;color:var(--ink);cursor:pointer}.faq-number{width:36px;height:36px;display:grid;place-items:center;border-radius:13px;background:var(--oat);font-family:var(--display);font-size:14px}.faq-q strong{font-size:12px;line-height:1.45}.faq-plus{width:32px;height:32px;display:grid;place-items:center;border-radius:12px;background:var(--pine-900);color:var(--acid);font-size:18px;transition:.25s}.faq-item.open .faq-plus{transform:rotate(45deg)}.faq-a{max-height:0;overflow:hidden;transition:max-height .38s ease}.faq-answer{padding:0 20px 22px 71px}.faq-answer p{margin:0;font-size:11px;line-height:1.75;color:rgba(22,35,30,.62)}.faq-answer ul{margin:13px 0 0;padding-left:18px;font-size:10px;line-height:1.75;color:rgba(22,35,30,.62)}.answer-links{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}.answer-link{padding:9px 11px;border:1px solid var(--line);border-radius:12px;background:var(--cream);font-size:9px;font-weight:800}.helpful{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:18px;padding-top:15px;border-top:1px solid var(--line)}.helpful span{font-size:9px;color:rgba(22,35,30,.46)}.helpful-actions{display:flex;gap:6px}.helpful-btn{width:34px;height:34px;display:grid;place-items:center;border:1px solid var(--line);border-radius:12px;background:white;cursor:pointer}.empty-state{display:none;padding:54px 24px;text-align:center;border:1px dashed rgba(9,37,29,.2);border-radius:26px}.empty-state.show{display:block}.empty-state h3{font-family:var(--display);font-size:30px;margin:0}.empty-state p{max-width:520px;margin:12px auto 20px;font-size:11px;line-height:1.7;color:rgba(22,35,30,.56)}
    .guide-section{padding:100px 0}.guide-grid{display:grid;grid-template-columns:.82fr 1.18fr;gap:24px}.guide-copy{padding:35px;border-radius:32px;background:var(--pine-900);color:white}.guide-copy p{font-size:12px;line-height:1.72;color:rgba(255,255,255,.6)}.guide-note{margin-top:25px;padding:17px;border:1px solid rgba(255,255,255,.11);border-radius:19px;background:rgba(255,255,255,.05)}.guide-note strong{display:block;font-family:var(--display);font-size:22px}.guide-note span{display:block;margin-top:6px;font-size:9px;line-height:1.55;color:rgba(255,255,255,.48)}.guide-panel{padding:28px;border:1px solid var(--line);border-radius:32px;background:var(--cream);box-shadow:var(--shadow)}.guide-step{display:none}.guide-step.active{display:block}.guide-step h3{font-family:var(--display);font-size:34px;line-height:1.05;margin:0 0 8px}.guide-step>p{margin:0 0 22px;font-size:11px;color:rgba(22,35,30,.56)}.guide-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.guide-option{min-height:130px;padding:17px;border:1px solid var(--line);border-radius:20px;background:white;text-align:left;cursor:pointer}.guide-option:hover{border-color:rgba(9,37,29,.3)}.guide-option strong{display:block;font-family:var(--display);font-size:20px}.guide-option span{display:block;margin-top:7px;font-size:9px;line-height:1.5;color:rgba(22,35,30,.48)}.guide-progress{display:flex;gap:6px;margin-bottom:22px}.guide-progress i{height:4px;flex:1;border-radius:999px;background:rgba(9,37,29,.1)}.guide-progress i.active{background:var(--acid)}.guide-result{padding:23px;border-radius:24px;background:var(--oat)}.guide-result small{font-size:8px;text-transform:uppercase;letter-spacing:.13em;color:rgba(22,35,30,.4)}.guide-result h4{font-family:var(--display);font-size:31px;margin:8px 0}.guide-result p{font-size:10px;line-height:1.65;color:rgba(22,35,30,.58)}.guide-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:17px}
    .support-cta{padding:76px 0;background:var(--ember)}.support-card{display:grid;grid-template-columns:1fr auto;gap:40px;align-items:center}.support-card h2{font-family:var(--display);font-size:clamp(38px,5vw,68px);line-height:.95;margin:0}.support-card p{max-width:700px;margin:16px 0 0;font-size:12px;line-height:1.68}.support-actions{display:flex;gap:9px;flex-wrap:wrap;justify-content:flex-end}
    footer{padding:72px 0 28px;background:var(--pine-950);color:white}.footer-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:70px}.footer-brand p{max-width:340px;font-size:11px;line-height:1.65;color:rgba(255,255,255,.46)}.footer-cols{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.footer-col h4{margin:0 0 14px;font-size:9px;text-transform:uppercase;letter-spacing:.14em;color:rgba(255,255,255,.35)}.footer-col a{display:block;margin:10px 0;font-size:11px;color:rgba(255,255,255,.66)}.footer-col a:hover{color:white}.footer-bottom{display:flex;justify-content:space-between;gap:20px;margin-top:52px;padding-top:22px;border-top:1px solid rgba(255,255,255,.09);font-size:9px;color:rgba(255,255,255,.36)}.toast{position:fixed;left:50%;bottom:22px;z-index:260;max-width:calc(100% - 28px);padding:13px 17px;border-radius:999px;background:var(--pine-900);color:white;box-shadow:var(--shadow-dark);font-size:10px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transform:translate(-50%,130%);transition:.35s}.toast.show{transform:translate(-50%,0)}[data-reveal]{opacity:0;transform:translateY(28px)}
