  <script>
  (()=>{
    'use strict';
    const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];
    const body=document.body, nav=$('#siteNav'), progress=$('#scrollProgress'), menu=$('#mobileMenu');
    const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
    function setMenu(open){menu?.classList.toggle('open',open);menu?.setAttribute('aria-hidden',String(!open));body.classList.toggle('menu-open',open)}
    $('#menuOpen')?.addEventListener('click',()=>setMenu(true));$('#menuClose')?.addEventListener('click',()=>setMenu(false));$('#menuBackdrop')?.addEventListener('click',()=>setMenu(false));
    function onScroll(){const y=scrollY,max=document.documentElement.scrollHeight-innerHeight;nav?.classList.toggle('scrolled',y>24);if(progress)progress.style.transform=`scaleX(${max>0?Math.min(1,y/max):0})`}addEventListener('scroll',onScroll,{passive:true});onScroll();
    if(!reduce&&'IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(28px)'},{opacity:1,transform:'none'}],{duration:650,easing:'cubic-bezier(.2,.75,.2,1)',fill:'forwards'});io.unobserve(e.target)}}),{threshold:.12});$$('[data-reveal]').forEach(el=>io.observe(el))}else{$$('[data-reveal]').forEach(el=>{el.style.opacity=1;el.style.transform='none'})}
    function animatePath(path,marker,duration=2200){if(!path||!marker||reduce)return;const length=path.getTotalLength();path.style.strokeDasharray=length;path.style.strokeDashoffset=length;path.animate([{strokeDashoffset:length},{strokeDashoffset:0}],{duration,easing:'cubic-bezier(.2,.75,.2,1)',fill:'forwards',delay:260});const start=performance.now()+260;function move(t){const p=Math.max(0,Math.min(1,(t-start)/duration)),pt=path.getPointAtLength(length*p);marker.setAttribute('cx',pt.x);marker.setAttribute('cy',pt.y);if(p<1)requestAnimationFrame(move)}requestAnimationFrame(move)}animatePath($('#heroRoute'),$('#heroMarker'));

    const faqItems=$$('.faq-item'), results=$('#resultsCount'), empty=$('#emptyState'), search=$('#heroSearch'), suggestions=$('#suggestions');let activeFilter='all',activeQuery='';
    const suggestionData=[['ploaie','Ce se întâmplă dacă plouă?'],['copii','Copiii au tarif separat?'],['schimb data','Pot schimba data rezervării?'],['parcare','Există parcare?'],['voucher','Cum verific un voucher?'],['echipament','Ce echipament trebuie să aduc?']];
    function normalize(v){return v.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim()}
    function applyFilters(scroll=true){const q=normalize(activeQuery);let visible=0;faqItems.forEach(item=>{const category=item.dataset.category,text=normalize(item.textContent+' '+item.dataset.keywords);const show=(activeFilter==='all'||category===activeFilter)&&(!q||text.includes(q));item.hidden=!show;if(show)visible++});results.textContent=`${visible} ${visible===1?'răspuns afișat':'răspunsuri afișate'}`;empty.classList.toggle('show',visible===0);if(scroll)$('#raspunsuri').scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'})}
    function setFilter(filter,scroll=true){activeFilter=filter;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));$$('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===filter));applyFilters(scroll)}
    $$('[data-filter]').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.filter)));$$('[data-category]').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.category)));
    function performSearch(value){activeQuery=value;search.value=value;suggestions.classList.remove('open');applyFilters(true)}
    search.addEventListener('input',()=>{const q=normalize(search.value);if(q.length<2){suggestions.classList.remove('open');return}const matches=suggestionData.filter(([key,label])=>normalize(key+' '+label).includes(q)).slice(0,5);suggestions.innerHTML=matches.map(([key,label])=>`<button class="suggestion" type="button" data-suggest="${key}"><strong>${label}</strong><span>Caută</span></button>`).join('');suggestions.classList.toggle('open',matches.length>0);$$('[data-suggest]',suggestions).forEach(b=>b.addEventListener('click',()=>performSearch(b.dataset.suggest)))});
    $('#searchSubmit').addEventListener('click',()=>performSearch(search.value));search.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();performSearch(search.value)}});$$('[data-query]').forEach(b=>b.addEventListener('click',()=>performSearch(b.dataset.query)));document.addEventListener('click',e=>{if(!e.target.closest('.hero-search'))suggestions.classList.remove('open')});
    $$('.faq-q').forEach(btn=>btn.addEventListener('click',()=>{const item=btn.closest('.faq-item'),open=item.classList.contains('open');faqItems.forEach(i=>{i.classList.remove('open');i.querySelector('.faq-a').style.maxHeight='0px'});if(!open){item.classList.add('open');const answer=item.querySelector('.faq-a');answer.style.maxHeight=answer.scrollHeight+'px'}}));
    const toast=$('#toast');function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2300)}$$('[data-helpful]').forEach(b=>b.addEventListener('click',()=>showToast(b.dataset.helpful==='yes'?'Mulțumim. Răspuns marcat ca util.':'Mulțumim. Vom îmbunătăți răspunsul.')));

    let guide={group:'',energy:''};const steps=$$('.guide-step'),bars=$$('.guide-progress i');
    function showStep(n){steps.forEach(s=>s.classList.toggle('active',Number(s.dataset.step)===n));bars.forEach((b,i)=>b.classList.toggle('active',i<n))}
    $$('[data-group]').forEach(b=>b.addEventListener('click',()=>{guide.group=b.dataset.group;showStep(2)}));$$('[data-energy]').forEach(b=>b.addEventListener('click',()=>{guide.energy=b.dataset.energy;const map={calm:['Explorer Pass','Acces general, poteci și ritm flexibil, fără rezervarea unei experiențe intense.'],balanced:[guide.group==='family'?'Family Trail':'Adventure Pass','Acces de o zi și o experiență principală, cu un ritm echilibrat.'],intense:['Summit Pass','Acces premium, experiențe multiple și prioritate pentru o zi intensă.']};const rec=map[guide.energy];$('#guideTitle').textContent=rec[0];$('#guideText').textContent=rec[1];showStep(3)}));$('#guideReset').addEventListener('click',()=>{guide={group:'',energy:''};showStep(1)});
    addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});applyFilters(false);
  })();
  </script>
</body>
</html>
